from pathlib import Path
p=Path('contrataciones.html')
s=p.read_text(encoding='utf-8')

def once(old,new,label):
    global s
    n=s.count(old)
    if n!=1:
        raise SystemExit(f'{label}: expected 1, got {n}')
    s=s.replace(old,new,1)

# Helper de capitalización para nombres de equipos.
old="function money(v){return '$'+new Intl.NumberFormat('es-AR').format(Number(v||0))}\n"
new="""function money(v){return '$'+new Intl.NumberFormat('es-AR').format(Number(v||0))}
function titleWords(v){return String(v||'').trim().toLocaleLowerCase('es-AR').replace(/(^|[\\s\\-\\/])([a-záéíóúüñ])/g,(m,sep,ch)=>sep+ch.toLocaleUpperCase('es-AR'))}
"""
once(old,new,'titleWords helper')

# Normalizar nombres al confirmar formulario público.
old="async function submitClient(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());const msg=$('#msg');msg.innerHTML='<div class=\"notice info\">Guardando confirmación…</div>';try{await saveBooking(currentDraft.id,{...data,status:'confirmado',confirmedAt:new Date().toISOString()});renderSuccess({...currentDraft,...data,status:'confirmado'})}catch(err){msg.innerHTML='<div class=\"notice err\">No pude guardar la confirmación. Revisá tu conexión y volvé a intentar.</div>'}}"
new="async function submitClient(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());data.home=titleWords(data.home);data.away=titleWords(data.away);const msg=$('#msg');msg.innerHTML='<div class=\"notice info\">Guardando confirmación…</div>';try{await saveBooking(currentDraft.id,{...data,status:'confirmado',confirmedAt:new Date().toISOString()});renderSuccess({...currentDraft,...data,status:'confirmado'})}catch(err){msg.innerHTML='<div class=\"notice err\">No pude guardar la confirmación. Revisá tu conexión y volvé a intentar.</div>'}}"
once(old,new,'normalize public form')

# Mostrar nombres capitalizados siempre y agregar botones Editar / Eliminar.
old="function bookingCard(b){const dl=dateLabel(b.date);const maps=b.address||b.venue?`<button class=\"btn small green maps\" data-id=\"${esc(b.id)}\">📍 Maps</button>`:'';const safeStatus=['pendiente','confirmado','realizado','cancelado'].includes(b.status)?b.status:'pendiente';return `<article class=\"booking status-${esc(safeStatus)}\" data-id=\"${esc(b.id)}\" data-status=\"${esc(safeStatus)}\"><div class=\"datebox\"><div class=\"d\">${dl.d}</div><div class=\"m\">${esc(dl.m)}</div></div><div><div class=\"versus\">${esc(b.home||'Equipo local')} <span style=\"color:#64748b\">vs</span> ${esc(b.away||'Equipo visitante')}</div><div class=\"meta\"><span>⚽ Categoría <strong>${esc(b.category||'Pendiente')}</strong></span><span>🏟️ <strong>${esc(b.venue||'Cancha pendiente')}</strong></span><span>📍 <strong>${esc(b.address||'Dirección pendiente')}</strong></span><span>📸 Llegar <strong>${esc(b.arrivalTime||'--:--')}</strong></span><span>⚽ Partido <strong>${esc(b.matchTime||'--:--')}</strong></span><span>💰 <strong>${money(b.payment)}</strong></span><span>👤 <strong>${esc(b.clientName||'Sin confirmar')}</strong></span></div><div style=\"margin-top:8px\"><span class=\"status ${esc(b.status||'pendiente')}\">${esc(b.status||'pendiente')}</span> <span class=\"muted\">${esc(b.id)}</span></div></div><div class=\"booking-actions\">${maps}<button class=\"btn small ghost copy\" data-id=\"${esc(b.id)}\">Copiar link</button><button class=\"btn small primary cal\" data-id=\"${esc(b.id)}\">Google Calendar</button><button class=\"btn small ghost ics\" data-id=\"${esc(b.id)}\">.ics</button><select class=\"input statusSel\" data-id=\"${esc(b.id)}\" style=\"padding:8px 10px;width:auto\"><option ${b.status==='pendiente'?'selected':''}>pendiente</option><option ${b.status==='confirmado'?'selected':''}>confirmado</option><option ${b.status==='realizado'?'selected':''}>realizado</option><option ${b.status==='cancelado'?'selected':''}>cancelado</option></select></div></article>`}"
new="""function bookingCard(b){const dl=dateLabel(b.date);const maps=b.address||b.venue?`<button class=\"btn small green maps\" data-id=\"${esc(b.id)}\">📍 Maps</button>`:'';const safeStatus=['pendiente','confirmado','realizado','cancelado'].includes(b.status)?b.status:'pendiente';const home=titleWords(b.home)||'Equipo Local';const away=titleWords(b.away)||'Equipo Visitante';return `<article class=\"booking status-${esc(safeStatus)}\" data-id=\"${esc(b.id)}\" data-status=\"${esc(safeStatus)}\"><div class=\"datebox\"><div class=\"d\">${dl.d}</div><div class=\"m\">${esc(dl.m)}</div></div><div><div class=\"versus\">${esc(home)} <span style=\"color:#64748b\">vs</span> ${esc(away)}</div><div class=\"meta\"><span>⚽ Categoría <strong>${esc(b.category||'Pendiente')}</strong></span><span>🏟️ <strong>${esc(b.venue||'Cancha pendiente')}</strong></span><span>📍 <strong>${esc(b.address||'Dirección pendiente')}</strong></span><span>📸 Llegar <strong>${esc(b.arrivalTime||'--:--')}</strong></span><span>⚽ Partido <strong>${esc(b.matchTime||'--:--')}</strong></span><span>💰 <strong>${money(b.payment)}</strong></span><span>👤 <strong>${esc(b.clientName||'Sin confirmar')}</strong></span></div><div style=\"margin-top:8px\"><span class=\"status ${esc(b.status||'pendiente')}\">${esc(b.status||'pendiente')}</span> <span class=\"muted\">${esc(b.id)}</span></div></div><div class=\"booking-actions\">${maps}<button class=\"btn small ghost editBooking\" data-id=\"${esc(b.id)}\">✏️ Editar</button><button class=\"btn small red deleteBooking\" data-id=\"${esc(b.id)}\">🗑 Eliminar</button><button class=\"btn small ghost copy\" data-id=\"${esc(b.id)}\">Copiar link</button><button class=\"btn small primary cal\" data-id=\"${esc(b.id)}\">Google Calendar</button><button class=\"btn small ghost ics\" data-id=\"${esc(b.id)}\">.ics</button><select class=\"input statusSel\" data-id=\"${esc(b.id)}\" style=\"padding:8px 10px;width:auto\"><option ${b.status==='pendiente'?'selected':''}>pendiente</option><option ${b.status==='confirmado'?'selected':''}>confirmado</option><option ${b.status==='realizado'?'selected':''}>realizado</option><option ${b.status==='cancelado'?'selected':''}>cancelado</option></select></div></article>`}
"""
once(old,new,'booking buttons and display')

# Agregar edición y borrado, y cablear botones.
old="function wireBookingButtons(){document.querySelectorAll('.copy').forEach(btn=>btn.onclick=async()=>{await navigator.clipboard.writeText(publicLink(btn.dataset.id));btn.textContent='Link copiado ✓';setTimeout(()=>btn.textContent='Copiar link',1300)});document.querySelectorAll('.maps').forEach(btn=>btn.onclick=async()=>{const b=await loadOne(btn.dataset.id);window.open(mapsUrl(b),'_blank')});document.querySelectorAll('.cal').forEach(btn=>btn.onclick=async()=>{const b=await loadOne(btn.dataset.id);window.open(calendarUrl(b),'_blank')});document.querySelectorAll('.ics').forEach(btn=>btn.onclick=async()=>downloadIcs(await loadOne(btn.dataset.id)));document.querySelectorAll('.statusSel').forEach(sel=>sel.onchange=async()=>{await saveBooking(sel.dataset.id,{status:sel.value});renderAdminList($('#search')?$('#search').value:'')})}"
new="""async function openEditBooking(id){const b=await loadOne(id);if(!b)return alert('No pude encontrar esta contratación.');const modal=document.createElement('div');modal.style='position:fixed;inset:0;background:rgba(0,0,0,.78);z-index:120;display:grid;place-items:center;padding:16px';modal.innerHTML=`<div class=\"card\" style=\"width:min(680px,100%);max-height:92vh;overflow:auto\"><div style=\"display:flex;justify-content:space-between;align-items:center;gap:12px\"><div><div class=\"eyebrow\">Editar contratación</div><h3 style=\"font-size:26px;margin:8px 0 5px\">${esc(titleWords(b.home)||'Equipo Local')} vs ${esc(titleWords(b.away)||'Equipo Visitante')}</h3></div><button type=\"button\" id=\"closeEdit\" class=\"btn ghost small\">✕</button></div><form id=\"editBookingForm\" class=\"formgrid\" style=\"margin-top:17px\"><div class=\"field\"><label>Fecha</label><input class=\"input\" type=\"date\" name=\"date\" value=\"${esc(b.date||'')}\"></div><div class=\"field\"><label>Hora partido</label><input class=\"input\" type=\"time\" name=\"matchTime\" value=\"${esc(b.matchTime||'')}\"></div><div class=\"field\"><label>Equipo local</label><input class=\"input\" name=\"home\" value=\"${esc(titleWords(b.home))}\"></div><div class=\"field\"><label>Equipo visitante</label><input class=\"input\" name=\"away\" value=\"${esc(titleWords(b.away))}\"></div><div class=\"field\"><label>Categoría</label><select class=\"input\" name=\"category\">${categoryOptions(b.category)}</select></div><div class=\"field\"><label>Hora de llegada</label><input class=\"input\" type=\"time\" name=\"arrivalTime\" value=\"${esc(b.arrivalTime||'')}\"></div><div class=\"field full\"><label>Cancha / estadio</label><input class=\"input\" name=\"venue\" value=\"${esc(b.venue||'')}\"></div><div class=\"field full\"><label>Dirección</label><input class=\"input\" name=\"address\" value=\"${esc(b.address||'')}\"></div><div class=\"field\"><label>Cliente</label><input class=\"input\" name=\"clientName\" value=\"${esc(b.clientName||'')}\"></div><div class=\"field\"><label>Teléfono</label><input class=\"input\" name=\"phone\" value=\"${esc(b.phone||'')}\"></div><div class=\"field\"><label>Pago acordado</label><input class=\"input\" type=\"number\" min=\"0\" name=\"payment\" value=\"${esc(b.payment||0)}\"></div><div class=\"field\"><label>Estado</label><select class=\"input\" name=\"status\"><option ${b.status==='pendiente'?'selected':''}>pendiente</option><option ${b.status==='confirmado'?'selected':''}>confirmado</option><option ${b.status==='realizado'?'selected':''}>realizado</option><option ${b.status==='cancelado'?'selected':''}>cancelado</option></select></div><div class=\"field full\"><label>Observaciones</label><textarea class=\"input\" rows=\"3\" name=\"notes\">${esc(b.notes||'')}</textarea></div><div class=\"field full\"><label>Nota privada</label><textarea class=\"input\" rows=\"2\" name=\"adminNote\">${esc(b.adminNote||'')}</textarea></div><div class=\"field full\"><div class=\"actions\"><button class=\"btn primary\" type=\"submit\">Guardar cambios</button><button class=\"btn ghost\" type=\"button\" id=\"cancelEdit\">Cancelar</button></div><div id=\"editMsg\"></div></div></form></div>`;document.body.appendChild(modal);const close=()=>modal.remove();$('#closeEdit').onclick=close;$('#cancelEdit').onclick=close;$('#editBookingForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());data.home=titleWords(data.home);data.away=titleWords(data.away);data.payment=Number(data.payment||0);$('#editMsg').innerHTML='<div class=\"notice info\">Guardando cambios…</div>';try{await saveBooking(id,data);close();await renderAdminList($('#search')?$('#search').value:'')}catch(err){$('#editMsg').innerHTML='<div class=\"notice err\">No pude guardar los cambios.</div>'}}}
async function deleteBooking(id){const b=await loadOne(id);if(!b)return;const label=`${titleWords(b.home)||'Equipo Local'} vs ${titleWords(b.away)||'Equipo Visitante'}`;if(!confirm(`¿Eliminar definitivamente ${label}? Esta acción no se puede deshacer.`))return;try{await bookingDoc(id).delete();await renderAdminList($('#search')?$('#search').value:'')}catch(err){alert('No pude eliminar la contratación. Revisá la conexión y probá nuevamente.')}}
function wireBookingButtons(){document.querySelectorAll('.editBooking').forEach(btn=>btn.onclick=()=>openEditBooking(btn.dataset.id));document.querySelectorAll('.deleteBooking').forEach(btn=>btn.onclick=()=>deleteBooking(btn.dataset.id));document.querySelectorAll('.copy').forEach(btn=>btn.onclick=async()=>{await navigator.clipboard.writeText(publicLink(btn.dataset.id));btn.textContent='Link copiado ✓';setTimeout(()=>btn.textContent='Copiar link',1300)});document.querySelectorAll('.maps').forEach(btn=>btn.onclick=async()=>{const b=await loadOne(btn.dataset.id);window.open(mapsUrl(b),'_blank')});document.querySelectorAll('.cal').forEach(btn=>btn.onclick=async()=>{const b=await loadOne(btn.dataset.id);window.open(calendarUrl(b),'_blank')});document.querySelectorAll('.ics').forEach(btn=>btn.onclick=async()=>downloadIcs(await loadOne(btn.dataset.id)));document.querySelectorAll('.statusSel').forEach(sel=>sel.onchange=async()=>{await saveBooking(sel.dataset.id,{status:sel.value});renderAdminList($('#search')?$('#search').value:'')})}
"""
once(old,new,'wire edit delete')

